      'from.australia.who.li1': 'Canadians on working holiday visas or living permanently in Australia',
      'from.australia.who.li2': 'Australian residents sending documents or letters to Canadian contacts',
      'from.australia.who.li3': 'Expats managing paperwork across two countries',
      'from.australia.who.li4': 'Anyone needing a letter delivered with Canadian postage',
      'from.australia.faq.q0': 'Can I use an Australian credit card?',
